// Forge's service worker — hand-written rather than generated by a build
// plugin. The app's build is a two-phase Vite → Nitro pipeline (see
// vite.config.ts's comment), and every workbox-based generator we tried
// wrote its output to whichever directory each phase happened to be using
// at that exact moment, so its `sw.js` never reliably ended up where Nitro
// actually serves static files from. A plain static file avoids that
// entirely — it's copied to the output the same way favicon.ico already is.
//
// Scope, deliberately: this does NOT try to precache the app's hashed JS/CSS
// bundle. That would mean keeping a manifest of exact build output filenames
// in sync by hand (the thing build plugins exist to automate), which isn't
// worth it for what this buys — everything the app needs is already fully
// functional offline via localStorage once a page has loaded once normally.
// What this SW does cache is the two things repeat/offline use actually
// benefits from: the OCR assets (so re-scanning doesn't re-fetch ~9MB) and
// the app shell's own HTML (so reopening the installed app with a flaky or
// absent connection still opens instead of showing a browser error).

// Bump this on any deploy where a stale cached shell (PAGES_CACHE) could
// end up referencing content-hashed JS/CSS filenames a newer deploy has
// since removed from the server — a mismatch that leaves an installed PWA
// stuck (see __root.tsx's stale-shell auto-reload script for the full
// story). Changing this string changes sw.js's own bytes, which is what
// makes the browser notice there's a new service worker to install at all;
// `activate` below then deletes every cache key not in CURRENT_CACHES,
// clearing the stale entry out from under any device still running the
// previous version.
const CACHE_VERSION = "v3";
const OCR_CACHE = `forge-ocr-${CACHE_VERSION}`;
const PAGES_CACHE = `forge-pages-${CACHE_VERSION}`;
const ASSETS_CACHE = `forge-assets-${CACHE_VERSION}`;
const CURRENT_CACHES = [OCR_CACHE, PAGES_CACHE, ASSETS_CACHE];

self.addEventListener("install", (event) => {
  self.skipWaiting();
  // Warm the shell during install so the very FIRST cold launch after an
  // install/reinstall already has it locally, instead of being the one
  // launch that still pays a full network round-trip for it. Best-effort:
  // a failure here must not abort the install, or the SW never activates.
  event.waitUntil(
    caches
      .open(PAGES_CACHE)
      .then((cache) => cache.add(new Request("/", { cache: "reload" })))
      .catch(() => undefined),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys.filter((key) => !CURRENT_CACHES.includes(key)).map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Build output under /assets/: cache-first, and safe to keep forever
  // without revalidation because every filename is content-hashed by Vite —
  // a changed file is a different URL, so a cache hit can never be stale.
  // This matters specifically for the render-blocking-ness of styles.css:
  // it gates the whole first paint, so on a cold launch with an evicted
  // HTTP cache it was a network round-trip the user saw as a white flash
  // (see __root.tsx's RootShell). HTTP Cache-Control already marks these
  // immutable, but Cache Storage survives iOS evicting the HTTP cache, so
  // the two are complementary rather than redundant.
  if (url.pathname.startsWith("/assets/")) {
    event.respondWith(
      caches.open(ASSETS_CACHE).then(async (cache) => {
        const cached = await cache.match(request);
        if (cached) return cached;
        const response = await fetch(request);
        if (response.ok) cache.put(request, response.clone());
        return response;
      }),
    );
    return;
  }

  // OCR assets: cache-first — they're versioned by path, not by content hash,
  // so once cached they're reused as-is until CACHE_VERSION changes above.
  if (url.pathname.startsWith("/tesseract/")) {
    event.respondWith(
      caches.open(OCR_CACHE).then(async (cache) => {
        const cached = await cache.match(request);
        if (cached) return cached;
        const response = await fetch(request);
        if (response.ok) cache.put(request, response.clone());
        return response;
      }),
    );
    return;
  }

  // App shell navigations: stale-while-revalidate, not network-first. A cold
  // launch of the installed PWA gates its very first paint on this request —
  // network-first meant that paint waited on a real round-trip every time
  // (DNS, TLS, Cloudflare's own cold start, whatever the radio's signal was
  // that moment), whose latency varies launch to launch. Until that response
  // starts arriving, nothing on the page — not the inline background style,
  // not color-scheme, nothing — has reached WebKit yet, so the launch image
  // was getting dismissed into a blank default canvas for a networkdependent
  // stretch of time: a white flash present on nearly every cold launch, but
  // with the exact timing/intensity of the flash tracking that request's
  // latency, matching reports of it varying launch to launch. Serving the
  // cached shell immediately (near-zero latency, so there's almost nothing
  // left for the launch image to hand off into) while still fetching a fresh
  // copy in the background keeps this fast on every subsequent cold launch
  // without ever going stale for more than one extra launch — the app's own
  // markup doesn't embed per-request server data (everything's hydrated from
  // localStorage client-side), so a cached shell is functionally identical
  // to a fresh one even across a deploy.
  //
  // One known limitation now: `__root.tsx`'s head() reads a
  // `forge-color-scheme` cookie (see server.ts's own withDocumentCaching)
  // to pick the SSR'd status-bar/theme-color meta values, so the "correct"
  // cached shell for "/" can now depend on that cookie — but a service
  // worker's `fetch` event genuinely CANNOT read the Cookie header at all:
  // it's one of the Fetch spec's "forbidden" header names, redacted from
  // `request.headers` in every context (page fetch, SW fetch event, no
  // exceptions), even though the browser still attaches the real cookie to
  // the actual outgoing network request underneath. An earlier attempt at
  // `request.headers.get("cookie")` here to skip the cache for
  // cookie-bearing requests looked like it worked in isolation (blocking
  // the SW entirely "fixed" the bug in testing) but was quietly dead code
  // in practice — the check always read as empty, so it never actually
  // took the network-only branch. Confirmed by reproducing the real
  // failure with the SW active: switch color scheme, then reload — the
  // reload can still show the stale (pre-switch) status bar/theme-color
  // once, if this cache already held an entry for "/" from before the
  // switch. It's bounded to exactly one extra launch, not permanently
  // stuck, because the `network` fetch below is unconditional regardless
  // of cache hit/miss — it still runs, still gets the CURRENT cookie's
  // correct response (the browser sends the real cookie on that req even
  // though this code can't read it), and still overwrites the cache via
  // `cache.put()`. So the launch immediately after a scheme change may
  // show the old bar once; the one after that is correct, since by then
  // the previous launch's background revalidation already refreshed the
  // cached entry. No SW-side fix closes that one-launch gap — there's no
  // spec-legal way for this code to know the current cookie ahead of the
  // fetch it's already making.
  if (request.mode === "navigate") {
    event.respondWith(
      caches.open(PAGES_CACHE).then(async (cache) => {
        const cached = await cache.match(request);
        const network = fetch(request)
          .then((response) => {
            if (response.ok) cache.put(request, response.clone());
            return response;
          })
          .catch(() => undefined);
        // When serving from cache, the revalidation fetch above is handed
        // to waitUntil instead of being awaited — otherwise, once this
        // handler already returned the cached response, the SW would be
        // free to terminate before that fetch/cache.put finished, and the
        // cache would silently stop refreshing.
        if (cached) {
          event.waitUntil(network);
          return cached;
        }
        return (await network) ?? Response.error();
      }),
    );
  }
});

// Rest-timer notifications sent by the send-rest-notifications edge function
// (see supabase/functions/) while the page itself may be fully suspended —
// this is what lets a rest-complete alert land with the screen locked.
self.addEventListener("push", (event) => {
  let payload = { title: "Rest complete", body: "Time to lift — back to Forge." };
  try {
    if (event.data) payload = { ...payload, ...event.data.json() };
  } catch {
    /* fall back to the default copy above */
  }
  event.waitUntil(
    self.registration.showNotification(payload.title, {
      body: payload.body,
      tag: "forge-rest",
      icon: "/pwa/icon-192.png",
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clients) => {
      const existing = clients.find((c) => "focus" in c);
      if (existing) return existing.focus();
      return self.clients.openWindow("/session");
    }),
  );
});
